//! 🏷️ Original dispatch tags capture actual window and tool addresses in bounded UTF-8 turns.
use super::*;
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalCallerSourceLoan,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneProgress,RetainedCloneStep,ValueRefusalKind};
use std::mem::{ManuallyDrop,size_of};
#[derive(Clone,Copy,PartialEq,Eq)]
pub enum OriginalToolTagKind{ScrubTick,ScrubCommit,ScrubAbort(ToolAbortReason),TypingEdit}
#[derive(Clone,Copy)]
pub enum OriginalToolWindow<'a>{Global,Window(&'a str)}
#[derive(Clone,Copy)]
pub struct OriginalToolTagSource<'a>{pub window:OriginalToolWindow<'a>,pub app:&'a str,pub action:&'a str,pub value:&'a str,pub kind:OriginalToolTagKind}
impl OriginalToolTagSource<'_>{fn window(&self)->&str{match self.window{OriginalToolWindow::Global=>"",OriginalToolWindow::Window(value)=>value}}fn identity(&self)->[(usize,usize);4]{let parts=[self.window(),self.app,self.action,self.value];parts.map(|value|(value.as_ptr()as usize,value.len()))}fn length(&self,field:usize)->Result<usize,ValueError>{match field{0=>Ok(self.window().len()),1=>self.app.len().checked_add(1).and_then(|n|n.checked_add(self.action.len())).ok_or_else(invalid),_=>Ok(self.value.len())}}fn byte(&self,field:usize,index:usize)->u8{match field{0=>self.window().as_bytes()[index],1=>if index<self.app.len(){self.app.as_bytes()[index]}else if index==self.app.len(){b'#'}else{self.action.as_bytes()[index-self.app.len()-1]},_=>self.value.as_bytes()[index]}}}
pub struct OriginalToolTagCapture{source_binding:OriginalSourceBinding,source_decoder:(u64,u64),binding:Option<OriginalSourceBinding>,decoder:Option<(u64,u64)>,caller:ManuallyDrop<Option<OriginalCallerSourceLoan>>,source:[(usize,usize);4],kind:OriginalToolTagKind,field:usize,parts:ControlledRetirement<[Vec<u8>;3]>,complete:bool,closing:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original tool tag changed its source or receiving caller")}
fn progress(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
fn original(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
impl OriginalToolTagCapture{
 pub fn admit(source:OriginalToolTagSource<'_>,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if output.is_some(){return Err(invalid().into())}let d=RetirementDemand{copy_bytes:2*size_of::<Self>(),capacity_bytes:size_of::<Self>(),depth:1,..Default::default()};let binding=OriginalSourceBinding::borrow(cx);admit_original_construction(cx,output,original(d),|native|{let decoder=(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::new(Self{source_binding:binding,source_decoder:decoder,binding:Some(binding),decoder:Some(decoder),caller:ManuallyDrop::new(None),source:source.identity(),kind:source.kind,field:0,parts:ControlledRetirement::retain(std::array::from_fn(|_|Vec::new())),complete:false,closing:false}),progress(d)))})}
 pub fn matches_context(&self,cx:&StepContext<'_>)->bool{self.source_binding.matches(cx)&&Some(self.source_decoder)==cx.native_receiving_identity()}
 pub fn accepts(&self,source:OriginalToolTagSource<'_>,cx:&StepContext<'_>)->bool{self.source==source.identity()&&self.kind==source.kind&&self.source_binding.matches(cx)&&Some(self.source_decoder)==cx.native_receiving_identity()}
 fn validate_source(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.is_some_and(|b|b.matches(cx))||self.decoder!=cx.native_receiving_identity(){return Err(invalid().into())}Ok(())}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{self.validate_source(cx)?;if let Some(caller)=self.caller.as_ref(){caller.validate_context(cx)?}Ok(())}
 pub fn advance(&mut self,source:OriginalToolTagSource<'_>,output:&mut Option<ToolTag>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing{return Err(invalid().into())}if self.complete{return if output.is_some(){Ok(true)}else{Err(invalid().into())}}if output.is_some()||source.identity()!=self.source||source.kind!=self.kind{return Err(invalid().into())}if self.caller.is_none(){let Some(caller)=cx.original_source_parent()?.admit_loan(cx)?else{return Ok(false)};*self.caller=Some(caller);return Ok(false)}
  let parts=self.parts.original_mut().ok_or_else(invalid)?;
  if self.field<3{let length=source.length(self.field)?;let field=self.field;if parts[field].capacity()<length{let d=RetirementDemand{copy_bytes:2*size_of::<Vec<u8>>(),capacity_bytes:length,depth:1,..Default::default()};let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{parts[field]=Vec::with_capacity(length);Ok(((),RetainedCloneProgress{retained_capacity_bytes:parts[field].capacity(),..progress(d)}))})?;return Ok(false)}if parts[field].len()<length{let start=parts[field].len();let count=(length-start).min(64);let d=RetirementDemand{copy_bytes:count+2*size_of::<usize>(),depth:1,..Default::default()};let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{for index in start..start+count{parts[field].push(source.byte(field,index))}Ok(((),progress(d)))})?;return Ok(false)}let d=RetirementDemand{copy_bytes:size_of::<usize>(),depth:1,..Default::default()};let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{self.field+=1;Ok(((),progress(d)))})?;return Ok(false)}
  let d=RetirementDemand{copy_bytes:2*size_of::<ToolTag>()+3*size_of::<Vec<u8>>()+size_of::<bool>(),depth:1,..Default::default()};admit_original_construction(cx,output,original(d),|_|{let window=String::from_utf8(std::mem::take(&mut parts[0])).expect("original window is UTF-8");let tool=String::from_utf8(std::mem::take(&mut parts[1])).expect("original tool is UTF-8");let value=String::from_utf8(std::mem::take(&mut parts[2])).expect("original tag value is UTF-8");let tag=match self.kind{OriginalToolTagKind::TypingEdit=>ToolTag::Typing(TypingTag{window,tool,buffer:value}),kind=>ToolTag::Scrub(ScrubTag{window,tool,phase:match kind{OriginalToolTagKind::ScrubTick=>ScrubPhase::Tick{gesture:value},OriginalToolTagKind::ScrubCommit=>ScrubPhase::Commit{gesture:value},OriginalToolTagKind::ScrubAbort(reason)=>ScrubPhase::Abort{gesture:value,reason},_=>unreachable!()}})};self.complete=true;Ok((tag,progress(d)))})
 }
 pub fn captured_bytes(&self)->usize{self.parts.original().map_or(0,|parts|parts.iter().map(Vec::len).sum())}
 pub fn complete(&self)->bool{self.complete}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.parts.terminal_is_empty(){return self.parts.next_demand(body)}if let Some(caller)=self.caller.as_ref(){return if caller.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<OriginalCallerSourceLoan>>(),depth:1,..Default::default()})}else{Ok(caller.retirement_demands())}}Ok(RetirementDemand{copy_bytes:size_of::<Option<OriginalSourceBinding>>()+size_of::<Option<(u64,u64)>>()+size_of::<bool>(),depth:1,..Default::default()})}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(())}self.validate_source(cx)?;if !self.parts.terminal_is_empty(){let d=self.close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|self.parts.step(g))?;return Ok(())}if let Some(caller)=self.caller.as_mut(){if !caller.terminal_is_empty(){caller.close_step(cx.original_source_parent()?,cx)?;return Ok(())}let d=self.close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|_|{self.caller.take();Ok(RetainedCloneStep::Progress(progress(d)))})?;return Ok(())}let d=self.close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|_|{self.binding=None;self.decoder=None;self.closing=true;Ok(RetainedCloneStep::Complete(progress(d)))})?;Ok(())}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.binding.is_none()&&self.caller.is_none()&&self.parts.terminal_is_empty()}
 pub fn shell_close_demands(&self)->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Box<Self>>>(),release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalToolTagCapture{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original tool tag requires paid physical source close")}}
